# kaliru plugin layer: mirror of Kalico klippy.extras.motion_report (generated by tools/gen_mirror.py)
import _k

from klippy import chelper
import logging
NEVER_TIME = 1e+16
STATUS_REFRESH_TIME = 0.25

class DumpStepper(_k.Object):
    __kaliru_mirror__ = True
    def __init__(self, printer, mcu_stepper):
        _k.new(self, 3656, printer, mcu_stepper)
    def get_step_queue(self, start_clock, end_clock):
        return _k.call(self, 3657, start_clock, end_clock)
    def log_steps(self, data):
        return _k.call(self, 3658, data)
    def _process_batch(self, eventtime):
        return _k.call(self, 3659, eventtime)
    batch_bulk = _k.Attr(3660, 'batch_bulk')
    last_batch_clock = _k.Attr(3661, 'last_batch_clock')
    mcu_stepper = _k.Attr(3662, 'mcu_stepper')
    printer = _k.Attr(3663, 'printer')

class DumpTrapQ(_k.Object):
    __kaliru_mirror__ = True
    def __init__(self, printer, name, trapq):
        _k.new(self, 3664, printer, name, trapq)
    def extract_trapq(self, start_time, end_time=NEVER_TIME):
        ffi_main, ffi_lib = chelper.get_ffi()
        res = []
        while True:
            data = ffi_main.new("struct pull_move[128]")
            count = ffi_lib.trapq_extract_old(
                self.trapq, data, len(data), start_time, end_time
            )
            if not count:
                break
            res.append((data, count))
            if count < len(data):
                break
            end_time = data[count - 1].print_time
        res.reverse()
        return ([d[i] for d, cnt in res for i in range(cnt - 1, -1, -1)], res)
    def log_trapq(self, data):
        if not data:
            return
        out = ["Dumping trapq '%s' %d moves:" % (self.name, len(data))]
        for i, m in enumerate(data):
            out.append(
                "move %d: pt=%.6f mt=%.6f sv=%.6f a=%.6f"
                " sp=(%.6f,%.6f,%.6f) ar=(%.6f,%.6f,%.6f)"
                % (
                    i,
                    m.print_time,
                    m.move_t,
                    m.start_v,
                    m.accel,
                    m.start_x,
                    m.start_y,
                    m.start_z,
                    m.x_r,
                    m.y_r,
                    m.z_r,
                )
            )
        logging.info("\n".join(out))
    def get_trapq_position(self, print_time):
        ffi_main, ffi_lib = chelper.get_ffi()
        data = ffi_main.new("struct pull_move[1]")
        count = ffi_lib.trapq_extract_old(self.trapq, data, 1, 0.0, print_time)
        if not count:
            return None, None
        move = data[0]
        move_time = max(0.0, min(move.move_t, print_time - move.print_time))
        dist = (move.start_v + 0.5 * move.accel * move_time) * move_time
        pos = (
            move.start_x + move.x_r * dist,
            move.start_y + move.y_r * dist,
            move.start_z + move.z_r * dist,
        )
        velocity = move.start_v + move.accel * move_time
        return pos, velocity
    def _process_batch(self, eventtime):
        return _k.call(self, 3668, eventtime)
    batch_bulk = _k.Attr(3669, 'batch_bulk')
    last_batch_msg = _k.Attr(3670, 'last_batch_msg')
    motion_queuing = _k.Attr(3671, 'motion_queuing')
    name = _k.Attr(3672, 'name')
    printer = _k.Attr(3673, 'printer')
    trapq = _k.Attr(3674, 'trapq')

